(function () {
  "use strict";

  var BG = "#232323";
  var RING = "rgba(255,255,255,0.22)";
  var WHITE = "#e8e8e8";
  var PING = [255, 74, 26];
  var PASTELS = ["#cbb8e0", "#e8c2b4", "#d8c7a4", "#ffffff"];
  var LABEL = { idle: "Click & hold", holding: "Keep holding", charged: "Release" };

  var RING_COUNT = 12;
  var RIPPLE_DURATION = 1.8;
  var RIPPLE_MAX_RADIUS = 1.6;
  var RIPPLE_WIDTH = 0.85;
  var RIPPLE_PUSH = 0.045;
  var RIPPLE_SCALE = 0.5;
  var HOLD_GATHER = 0.12;
  var HOLD_SHAKE = 0.002;
  var HOLD_SHAKE_FRAC = 0.18;
  var HOLD_GLITCH_RATE = 9;
  var HOLD_GLITCH_FRAC = 0.15;
  var ENTRANCE_FADE = 0.5;
  var CHARGE_TIME = 0.9;
  var DOT_SIZE = 5;

  function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
  function lerp(a, b, t) { return a + (b - a) * t; }
  function smooth(e0, e1, x) {
    if (e0 === e1) return x < e0 ? 0 : 1;
    var t = clamp((x - e0) / (e1 - e0), 0, 1);
    return t * t * (3 - 2 * t);
  }
  function inverseSmooth(x) {
    if (x <= 0) return 0;
    if (x >= 1) return 1;
    var t = x;
    for (var i = 0; i < 6; i++) {
      var t2 = t * t;
      var f = 3 * t2 - 2 * t2 * t - x;
      var d = 6 * t - 6 * t2;
      if (d === 0) break;
      t -= f / d;
    }
    return clamp(t, 0, 1);
  }
  function hexRgb(hex) {
    var n = parseInt(hex.slice(1), 16);
    return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
  }
  function mixRgb(a, b, t) {
    return [
      Math.round(lerp(a[0], b[1] === undefined ? b[0] : b[0], t)),
      Math.round(lerp(a[1], b[1], t)),
      Math.round(lerp(a[2], b[2], t))
    ];
  }

  function buildRings() {
    var rings = [];
    for (var i = 0; i < RING_COUNT; i++) {
      var n = i / (RING_COUNT - 1);
      var radius = 0.08 + 1.32 * n;
      rings.push({
        radius: radius,
        speed: (i % 2 === 0 ? 1 : -1) * (0.008 + (1 - n) * 0.022),
        arrival: 1.8 * inverseSmooth(Math.min(1, Math.max(0, radius - 0.425) / 1.6))
      });
    }
    return rings;
  }

  function buildShapes(rings) {
    var shapes = [];
    for (var i = 0; i < rings.length; i++) {
      var ring = rings[i];
      var count = i < 3 ? 2 : (i < 7 ? 3 + (i % 2) : 4 + (i % 3));
      for (var n = 0; n < count; n++) {
        var kind = Math.random() < 0.55 ? "square" : "dot";
        var pastel = PASTELS[Math.floor(Math.random() * PASTELS.length)];
        shapes.push({
          ring: i,
          theta0: (n / count) * Math.PI * 2 + (Math.random() - 0.5) * 0.7,
          kind: kind,
          size: kind === "square" ? 6 + i * 0.35 : 3.2,
          color: hexRgb(pastel === "#ffffff" ? WHITE : pastel),
          seed: Math.random() * 1000,
          shakeSeed: Math.random()
        });
      }
    }
    return shapes;
  }

  function vt(el, opts) {
    opts = opts || {};
    var bg = opts.background || BG;
    var showLabel = opts.showLabel !== false;
    var wheelKick = opts.wheelKick !== false;

    var cs = getComputedStyle(el);
    if (cs.position === "static") el.style.position = "relative";
    if (cs.overflow === "visible") el.style.overflow = "hidden";
    el.style.cursor = "pointer";
    el.style.userSelect = "none";
    if (!el.style.backgroundColor && !el.style.background) el.style.backgroundColor = bg;

    var label = null;
    if (showLabel) {
      label = document.createElement("div");
      label.dataset.spiralLabel = "1";
      label.setAttribute("aria-hidden", "true");
      Object.assign(label.style, {
        position: "absolute",
        top: "0",
        left: "0",
        zIndex: "2",
        pointerEvents: "none",
        fontFamily: "ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace",
        fontSize: "11px",
        letterSpacing: "0.08em",
        textTransform: "uppercase",
        color: "rgba(255,255,255,0.7)",
        opacity: "0",
        transition: "opacity 120ms ease",
        whiteSpace: "nowrap"
      });
      label.textContent = LABEL.idle;
      el.appendChild(label);
    }

    function setLabel(k) { if (label) label.textContent = LABEL[k]; }
    function showLabelEl(on) { if (label) label.style.opacity = on ? "1" : "0"; }
    function moveLabel(x, y) {
      if (!label) return;
      var r = el.getBoundingClientRect();
      label.style.transform = "translate(" + (x - r.left + 14) + "px," + (y - r.top + 14) + "px)";
    }

    Array.from(el.children).forEach(function (child) {
      if (child.tagName === "CANVAS") el.removeChild(child);
    });

    var canvas = document.createElement("canvas");
    Object.assign(canvas.style, {
      width: "100%",
      height: "100%",
      display: "block",
      position: "absolute",
      inset: "0"
    });
    el.appendChild(canvas);
    var ctx = canvas.getContext("2d", { alpha: false });

    var rings = buildRings();
    var shapes = buildShapes(rings);
    var dpr = 1, W = 1, H = 1, cx = 0, cy = 0, fit = 1;

    var reduceMq = window.matchMedia("(prefers-reduced-motion: reduce)");
    var visible = true, inView = true, motion = !reduceMq.matches;
    var time = 0, last = performance.now(), raf = 0;
    var mouse = { x: 999, y: 999, tx: 999, ty: 999, inf: 0, tInf: 0 };
    var holding = false, charged = false, charge = 0, gather = 0;
    var ringCharge = new Float32Array(RING_COUNT);
    var ringGather = new Float32Array(RING_COUNT);
    var ringHoldOff = new Float32Array(RING_COUNT);
    var ringSpin = new Float32Array(RING_COUNT);
    var ringSpinT = new Float32Array(RING_COUNT);
    var ripples = [];
    var lastRipple = -1;
    var pings = [];
    var wheel = 0, wheelSmooth = 0;
    var pendingResize = false, resizeTimer = null, resizeAgain = false;

    function resize() {
      var r = el.getBoundingClientRect();
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      W = Math.max(1, r.width);
      H = Math.max(1, r.height);
      canvas.width = Math.floor(W * dpr);
      canvas.height = Math.floor(H * dpr);
      canvas.style.width = W + "px";
      canvas.style.height = H + "px";
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      cx = W * 0.5;
      cy = H * 0.5;
      fit = Math.min(W, H) * 0.42 / 1.4;
    }

    function toDesign(clientX, clientY) {
      var r = el.getBoundingClientRect();
      return {
        x: (clientX - r.left - cx) / fit,
        y: (clientY - r.top - cy) / fit
      };
    }

    function addRipple(strength, clientX, clientY) {
      ripples.push({ start: time, strength: strength });
      if (ripples.length > 16) ripples.shift();
      lastRipple = time;
      var p = clientX != null ? toDesign(clientX, clientY) : { x: 0.85, y: 0.55 };
      pings.push({
        born: time,
        x: p.x,
        y: p.y,
        life: 1.6
      });
      if (pings.length > 4) pings.shift();
    }

    function rippleAt(radius) {
      var max = 0;
      for (var i = 0; i < ripples.length; i++) {
        var rp = ripples[i];
        var elapsed = time - rp.start;
        if (elapsed < 0 || elapsed >= RIPPLE_DURATION) continue;
        var t = elapsed / RIPPLE_DURATION;
        var wave = smooth(0, 1, t) * RIPPLE_MAX_RADIUS;
        var bell = 1 - smooth(0, RIPPLE_WIDTH * 0.5, Math.abs(radius - wave));
        var life = smooth(0, 0.22, t) * (1 - smooth(0.78, 1, t));
        max = Math.max(max, bell * life);
      }
      return max;
    }

    function drawDottedRing(radiusPx) {
      var dash = Math.max(1.6, radiusPx * 0.018);
      ctx.save();
      ctx.strokeStyle = RING;
      ctx.lineWidth = 1;
      ctx.setLineDash([dash, dash * 1.7]);
      ctx.beginPath();
      ctx.arc(cx, cy, radiusPx, 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();
    }

    function drawShape(kind, x, y, size, rgb, alpha) {
      ctx.globalAlpha = alpha;
      ctx.fillStyle = "rgb(" + rgb[0] + "," + rgb[1] + "," + rgb[2] + ")";
      if (kind === "square") {
        var h = size * 0.5;
        ctx.fillRect(x - h, y - h, size, size);
      } else {
        ctx.beginPath();
        ctx.arc(x, y, size * 0.5, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.globalAlpha = 1;
    }

    function drawPing(p) {
      var t = (time - p.born) / p.life;
      if (t >= 1) return false;
      var fade = t < 0.15 ? t / 0.15 : 1 - Math.max(0, (t - 0.55) / 0.45);
      var x = cx + p.x * fit;
      var y = cy + p.y * fit;
      var bloom = (6 + t * 22) * (fit / 180);
      bloom = Math.max(10, bloom);

      ctx.save();
      ctx.globalCompositeOperation = "lighter";
      var g = ctx.createRadialGradient(x, y, 0, x, y, bloom);
      g.addColorStop(0, "rgba(" + PING[0] + "," + PING[1] + "," + PING[2] + "," + (0.95 * fade) + ")");
      g.addColorStop(0.35, "rgba(" + PING[0] + "," + PING[1] + "," + PING[2] + "," + (0.35 * fade) + ")");
      g.addColorStop(1, "rgba(" + PING[0] + "," + PING[1] + "," + PING[2] + ",0)");
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(x, y, bloom, 0, Math.PI * 2);
      ctx.fill();
      for (var i = 1; i <= 3; i++) {
        var rr = 8 + t * (18 + i * 14);
        ctx.strokeStyle = "rgba(" + PING[0] + "," + PING[1] + "," + PING[2] + "," + (0.55 * fade * (1 - i / 4)) + ")";
        ctx.lineWidth = 1.2;
        ctx.setLineDash([]);
        ctx.beginPath();
        ctx.arc(x, y, rr, 0, Math.PI * 2);
        ctx.stroke();
      }
      ctx.restore();
      return true;
    }

    function frame(now) {
      var dt = Math.min(0.05, (now - last) * 0.001);
      last = now;
      if (motion) time += dt;

      while (ripples.length && time - ripples[0].start >= RIPPLE_DURATION) ripples.shift();

      var kInf = 1 - Math.exp(-6 * dt);
      mouse.inf += (mouse.tInf - mouse.inf) * kInf;
      var kM = 1 - Math.exp(-14 * dt);
      mouse.x += (mouse.tx - mouse.x) * kM;
      mouse.y += (mouse.ty - mouse.y) * kM;

      if (holding) {
        charge = Math.min(1, charge + dt / CHARGE_TIME);
        gather = 1 - (1 - gather) * Math.exp(-dt / 4);
        if (!charged && charge >= 1) {
          charged = true;
          setLabel("charged");
        }
      } else {
        charge *= Math.exp(-10 * dt);
        gather *= Math.exp(-10 * dt);
      }

      var decay = Math.exp(-10 * dt);
      var sinceRipple = time - lastRipple;
      var rippling = lastRipple >= 0 && sinceRipple < RIPPLE_DURATION;
      var waveR = rippling ? RIPPLE_MAX_RADIUS * smooth(0, 1, sinceRipple / RIPPLE_DURATION) + 0.425 : Infinity;

      for (var i = 0; i < RING_COUNT; i++) {
        var rc = ringCharge[i];
        var rg = ringGather[i];
        if (holding) {
          var e = 1 - Math.exp(-14 * dt);
          rc += (charge - rc) * e;
          rg += (smooth(0, 1, charge) * gather - rg) * e;
        } else if (!rippling || waveR >= rings[i].radius) {
          rc *= decay;
          rg *= decay;
        }
        ringCharge[i] = rc;
        ringGather[i] = rg;
        ringHoldOff[i] -= rc * rings[i].speed * dt;
      }

      wheel *= Math.exp(-5 * dt);
      wheelSmooth += (Math.min(40, Math.abs(wheel)) - wheelSmooth) * (1 - Math.exp(-4 * dt));
      var kSpin = 1 - Math.exp(-3 * dt);
      for (var r = 0; r < RING_COUNT; r++) {
        var ring = rings[r];
        var kick = 0;
        for (var v = 0; v < ripples.length; v++) {
          var rp = ripples[v];
          var elp = time - rp.start;
          if (elp < 0 || elp >= RIPPLE_DURATION) continue;
          var tt = elp / RIPPLE_DURATION;
          var wr = RIPPLE_MAX_RADIUS * smooth(0, 1, tt);
          var o = (1 - smooth(0, 0.425, Math.abs(ring.radius - wr))) *
            (smooth(0, 0.22, tt) * (1 - smooth(0.78, 1, tt))) * rp.strength;
          if (o > kick) kick = o;
        }
        var dir = Math.sign(ring.speed) || 1;
        ringSpin[r] += (0.55 * kick * dir + ring.speed * wheelSmooth) * dt;
        ringSpinT[r] += (ringSpin[r] - ringSpinT[r]) * kSpin;
      }

      ctx.fillStyle = bg;
      ctx.fillRect(0, 0, W, H);

      for (var d = 0; d < RING_COUNT; d++) {
        drawDottedRing(rings[d].radius * (1 - ringGather[d] * HOLD_GATHER) * fit);
      }

      var whiteAmt = 0.5 + 0.5 * Math.sin(time * 0.35);
      var glitchTick = Math.floor(time * HOLD_GLITCH_RATE);

      for (var s = 0; s < shapes.length; s++) {
        var sh = shapes[s];
        var ring = rings[sh.ring];
        var rip = rippleAt(ring.radius);
        var gatherAmt = ringGather[sh.ring];
        var holdC = ringCharge[sh.ring];
        var radius = ring.radius * (1 - gatherAmt * HOLD_GATHER) + rip * RIPPLE_PUSH;
        var theta = sh.theta0 + time * ring.speed + ringSpinT[sh.ring] + ringHoldOff[sh.ring];
        var rx = Math.cos(theta) * radius;
        var ry = Math.sin(theta) * radius;

        var mdx = rx - mouse.x;
        var mdy = ry - mouse.y;
        var hover = (1 - smooth(0, 0.35, Math.sqrt(mdx * mdx + mdy * mdy))) * mouse.inf;
        var strength = Math.max(hover * 2.5, rip);
        var threshold = ((Math.sin(sh.seed * 12.9898) * 43758.5453) % 1 + 1) % 1;
        var isDot = threshold < strength;
        var glitchNoise = ((Math.sin(sh.seed * 91.7 + glitchTick * 7.31) * 43758.5453) % 1 + 1) % 1;
        if (glitchNoise < holdC * HOLD_GLITCH_FRAC) isDot = true;

        var sizePx = (isDot ? DOT_SIZE : sh.size) * (1 + rip * RIPPLE_SCALE);
        var shakes = sh.shakeSeed < HOLD_SHAKE_FRAC;
        var tremorX = 0, tremorY = 0;
        if (shakes && holdC > 0.01) {
          tremorX = Math.sin(time * (38 + sh.shakeSeed * 14) + sh.shakeSeed * 271) * holdC * HOLD_SHAKE;
          tremorY = Math.cos(time * (34 + sh.shakeSeed * 17) + sh.shakeSeed * 113) * holdC * HOLD_SHAKE;
        }

        var x = cx + (rx + tremorX) * fit;
        var y = cy + (ry + tremorY) * fit;
        var alpha = clamp((time - ring.arrival) / ENTRANCE_FADE, 0, 1);
        var rgb = mixRgb(sh.color, hexRgb(WHITE), isDot ? 1 : whiteAmt);
        if (rip > 0.35) rgb = mixRgb(rgb, PING, clamp((rip - 0.35) / 0.65, 0, 1));
        drawShape(isDot ? "dot" : sh.kind, x, y, sizePx * (fit / 180) * 1.15, rgb, alpha);
      }

      pings = pings.filter(drawPing);

      if (visible && inView && motion) raf = requestAnimationFrame(frame);
      else raf = 0;
    }

    function renderOnce() {
      last = performance.now();
      frame(last);
    }

    function kickLoop() {
      if (visible && inView && motion) {
        if (!raf) {
          last = performance.now();
          raf = requestAnimationFrame(frame);
        }
      } else {
        if (raf) cancelAnimationFrame(raf);
        raf = 0;
        renderOnce();
      }
    }

    function doResize() {
      resize();
      if (!raf) renderOnce();
    }

    var ac = new AbortController();
    var signal = ac.signal;
    var ro = new ResizeObserver(function () {
      if (!inView) { pendingResize = true; return; }
      if (resizeTimer == null) doResize();
      else resizeAgain = true;
      clearTimeout(resizeTimer);
      resizeTimer = setTimeout(function () {
        resizeTimer = null;
        if (resizeAgain) { resizeAgain = false; doResize(); }
      }, 150);
    });
    ro.observe(el);

    var io = new IntersectionObserver(function (entries) {
      var e0 = entries[0];
      if (!e0) return;
      inView = e0.isIntersecting;
      if (inView && pendingResize) { pendingResize = false; resize(); }
      kickLoop();
    }, { threshold: 0 });
    io.observe(el);

    document.addEventListener("visibilitychange", function () {
      visible = !document.hidden;
      kickLoop();
    }, { signal: signal });

    reduceMq.addEventListener("change", function () {
      motion = !reduceMq.matches;
      kickLoop();
    }, { signal: signal });

    if (wheelKick) {
      window.addEventListener("wheel", function (e) {
        wheel += e.deltaY * 0.15;
      }, { signal: signal, passive: true });
    }

    el.addEventListener("pointermove", function (e) {
      var p = toDesign(e.clientX, e.clientY);
      mouse.tx = p.x;
      mouse.ty = p.y;
      moveLabel(e.clientX, e.clientY);
    }, { signal: signal });

    el.addEventListener("pointerenter", function (e) {
      var p = toDesign(e.clientX, e.clientY);
      mouse.tx = mouse.x = p.x;
      mouse.ty = mouse.y = p.y;
      mouse.tInf = 1;
      showLabelEl(true);
      moveLabel(e.clientX, e.clientY);
    }, { signal: signal });

    el.addEventListener("pointerleave", function () {
      mouse.tInf = 0;
      holding = false;
      charged = false;
      setLabel("idle");
      showLabelEl(false);
    }, { signal: signal });

    el.addEventListener("pointerdown", function () {
      holding = true;
      charged = false;
      setLabel("holding");
    }, { signal: signal });

    function onUp(e) {
      if (!holding) return;
      holding = false;
      if (charged) addRipple(0.7 + 0.6 * gather, e && e.clientX, e && e.clientY);
      charged = false;
      setLabel("idle");
    }
    el.addEventListener("pointerup", onUp, { signal: signal });
    el.addEventListener("pointercancel", onUp, { signal: signal });

    resize();
    if (motion) addRipple(1, cx + 0.85 * fit, cy + 0.55 * fit);
    else time = 2.3;
    renderOnce();
    kickLoop();

    return {
      canvas: canvas,
      destroy: function () {
        if (raf) cancelAnimationFrame(raf);
        ac.abort();
        io.disconnect();
        ro.disconnect();
        if (resizeTimer) clearTimeout(resizeTimer);
        try { el.removeChild(canvas); } catch (e) {}
        if (label) try { el.removeChild(label); } catch (e) {}
      }
    };
  }

  var mounts = new WeakMap();
  var inited = false;

  function resolveEl(target) {
    if (!target) return document.getElementById("spiral-mount");
    return typeof target === "string" ? document.querySelector(target) : target;
  }

  function isOpts(v) {
    return !!(v && typeof v === "object" && !(v instanceof HTMLElement) && typeof v.nodeType !== "number");
  }

  function mergeOpts(e) {
    var cfg = window.SpiralMountConfig || {};
    var extra = e || {};
    return Object.assign({}, cfg, extra);
  }

  function init(target, opts) {
    inited = true;
    var el, options;
    if (opts === undefined && isOpts(target)) {
      el = target.target;
      options = target;
    } else {
      el = target;
      options = opts;
    }
    el = resolveEl(el);
    if (!el) {
      console.warn('[Spiral] No mount element found. Add a Div Block with id="spiral-mount".');
      return null;
    }
    mounts.get(el) && mounts.get(el).destroy();
    Array.from(el.children).forEach(function (child) {
      if (child.tagName === "CANVAS" || (child.dataset && child.dataset.spiralLabel === "1")) {
        child.remove();
      }
    });
    var inst = vt(el, mergeOpts(options));
    if (inst) mounts.set(el, inst);
    return inst;
  }

  window.SpiralMount = { init: init, createSpiral: vt };

  function auto() {
    if (inited) return;
    var cfg = window.SpiralMountConfig;
    if (cfg && cfg.auto === false) return;
    var el = resolveEl((cfg && cfg.target) || "#spiral-mount");
    if (!el || mounts.has(el)) return;
    var inst = vt(el, mergeOpts());
    if (inst) mounts.set(el, inst);
  }

  function boot() {
    var run = function () { setTimeout(auto, 0); };
    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", run, { once: true });
    } else {
      run();
    }
  }
  boot();
})();
